import sys as _sys, os as _os, json as _json, re as _re
SD = '/srv/kb/worker/builtin_engine/scripts'
if SD not in _sys.path:
    _sys.path.insert(0, SD)
_os.environ.setdefault('KB_API_BASE_URL', 'http://api-server:8000')
import weknora_rpc as wr
wr.load_config()
KB = str(bindings.get('kb_id') or '')
if KB:
    wr.KB = KB
    _os.environ['WEKNORA_KB_ID'] = KB
wr.mcp_init()

OUT = '/tmp/evolution'
raw = str(bindings.get('version_raw') or '') or str(bindings.get('version_plan') or '')
m = _re.search(r'\{.*\}', raw, _re.S)
if not m:
    raise RuntimeError('版本链解析失败: ' + raw[:200])
plan = _json.loads(m.group(0))
families_plan = plan.get('families') if isinstance(plan, dict) else plan
if not isinstance(families_plan, list) or not families_plan:
    raise RuntimeError('版本链为空')
data = _json.load(open(_os.path.join(OUT, 'families.json'), encoding='utf-8'))
all_docs = {d['idx']: d for d in data['docs']}

# 根下「制度版本演进」目录
root_fid = ''
try:
    for f in wr.list_all_folders_cached(kb_id=KB):
        if f.get('name') == '制度版本演进' and not (f.get('parent_id') or ''):
            root_fid = f.get('id') or ''
            break
except Exception as e:
    print('[n3] 目录缓存不可用:', e)
if not root_fid:
    r = wr.create_folder('制度版本演进', parent_id='', kb_id=KB)
    root_fid = ((r.get('data') or {}) if isinstance(r, dict) else {}).get('id') or ''
if not root_fid:
    raise RuntimeError('创建「制度版本演进」目录失败')
bindings['evolution_folder_id'] = root_fid
print('[n3] 根目录:', root_fid)

# 全库真实 slug 集合（双链校验：LLM 自造 slug 降级纯文本，防 broken_link）
known_slugs = set()
try:
    page_no = 1
    while True:
        rg = wr.list_wiki_pages(kb_id=KB, page=page_no, page_size=300)
        pages = rg.get('pages') or []
        if not pages:
            break
        for p in pages:
            known_slugs.add(str(p.get('slug') or ''))
        if len(pages) < 300:
            break
        page_no += 1
except Exception as e:
    print('[n3] slug 集合拉取失败:', e)


def _link_rep(mm):
    slug = mm.group(1)
    disp = mm.group(2) or slug
    return ('[[%s|%s]]' % (slug, disp)) if slug in known_slugs else disp


def _fix_links(text):
    return _re.sub(r'\[\[([^\[\]\|]+)(?:\|([^\[\]]*))?\]\]', _link_rep, text)


pages = []
for fp in families_plan:
    core = str(fp.get('core') or '').strip()
    versions = fp.get('versions') or []
    if not core or not versions:
        continue
    members = []
    for v in versions:
        try:
            d = all_docs.get(int(v.get('idx', 0)))
        except Exception:
            d = None
        if d:
            d['version_info'] = v
            members.append(d)
    if not members:
        print('[n3] 家族「%s」无有效成员，跳过' % core)
        continue
    # 素材：各版本摘要 + 原文页双链 + 摘要页双链
    src_parts = ['### 家族「%s」版本演进素材' % core]
    for mm in members:
        vi = mm.get('version_info') or {}
        src_parts.append('#### %s（%s，状态:%s，关系:%s）' % (
            mm['name'], mm['version'] or '未标注', vi.get('status', '?'), vi.get('relation', '?')))
        if mm.get('summary'):
            src_parts.append(mm['summary'])
        for sp in (mm.get('sum_pages') or [])[:3]:
            src_parts.append('- 摘要页：[[%s|%s]]' % (sp['slug'], sp['title']))
        for sp in (mm.get('src_pages') or [])[:15]:
            src_parts.append('- 原文页：[[%s|%s]]' % (sp['slug'], sp['title']))
    src = '\n'.join(src_parts)

    prompt = (
        '以下是同一文件家族「%s」的 %d 个版本（含各版本摘要与可引用原文页，slug 全部真实）。\n' % (core, len(members)) +
        '请生成该家族的「版本演进总览」wiki 页（通用业务文件版本演进，不限于任何行业），四段式结构：\n'
        '1. ## 一、版本演进链：表格 | 版本 | 文号/标识 | 状态 | 废止/替代关系 | 原文依据 |（原文依据用材料中真实 summary 双链）\n'
        '2. ## 二、逐版本内容迭代：按版本顺序（最早→最新），每个版本一段「版本要点」（每条要点链材料中真实原文 slug 佐证），相邻版本之间一段迭代表：| # | 迭代方向 | 具体变化 | 原文依据 | 原文核验 |，原文依据列必须双链（旧版+新版各至少一条真实 slug）；原文核验列只能填三态之一：✅原文印证（原文长句可定位）/ ⚠️原文存疑（摘要声称但原文未定位到）/ ➖无原文（该版无独立文档）；\n'
        '3. ## 三、版本演进洞察与实操提醒：趋势归纳（制度定位/适用范围/管理颗粒度等维度变化）+ 实操风险提示（从迭代中归纳，不引入新事实）；\n'
        '4. ## 四、知识推导过程：检索→溯源→比对→原文核验→归纳 简述；\n'
        '硬性要求：\n'
        '- 所有差异/要点必须链材料中出现的真实 slug（[[summary/...]] 或 [[longsentence/...]] 或 [[original_sentence/...]]）；\n'
        '- 某版本在库内无独立文档/无原文页时，该版要点写「该版在库内无独立文档，无法提取内容要点」，禁止编造；\n'
        '- 禁止出现「（依据摘要页）」「（推断）」「（依据）」等占位臆断文字；\n'
        '- 中文 Markdown，1000~2200 字，只输出正文（不含 # 标题）。双链只能用材料中出现的真实 slug。\n\n' + src
    )
    try:
        content = str(wr.llm_call([{'role': 'user', 'content': prompt}],
                                  max_tokens=6000, temperature=0.3) or '').strip()
    except Exception as e:
        print('[n3] 家族「%s」生成失败: %s' % (core, e))
        continue
    if not content:
        print('[n3] 家族「%s」内容为空，跳过' % core)
        continue
    content = _fix_links(content)
    pages.append({
        'title': core + '版本演进总览',
        'content': '# %s 版本演进总览\n\n> ⚠️ 本文以现行生效版为准，历史版本仅作沿革参考。\n\n%s' % (core, content),
        'source_refs': ['%s|%s' % (mm['doc_id'], mm['name']) for mm in members],
    })
    print('[n3] 家族「%s」: %d 版本, %d 字' % (core, len(members), len(content)))

_json.dump(pages, open(_os.path.join(OUT, 'ev_pages.json'), 'w', encoding='utf-8'),
           ensure_ascii=False, indent=1)
bindings['evolution_pages'] = len(pages)
print('[n3] 生成 %d 个版本演进页 → %s/ev_pages.json' % (len(pages), OUT))

